import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import StatCard from '../../components/common/StatCard';
import FeeBarChart from '../../components/charts/FeeBarChart';
import AttendanceLineChart from '../../components/charts/AttendanceLineChart';
import Avatar from '../../components/common/Avatar';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import API from '../../utils/api';
import { feeStatusColor } from '../../utils/helpers';
import toast from 'react-hot-toast';

const feeChartData = [
  { month: 'Nov', amount: 182000 }, { month: 'Dec', amount: 220000 },
  { month: 'Jan', amount: 195000 }, { month: 'Feb', amount: 241000 },
  { month: 'Mar', amount: 208000 }, { month: 'Apr', amount: 215000 },
];

const attChartData = [
  { label: 'Mon', pct: 88 }, { label: 'Tue', pct: 91 },
  { label: 'Wed', pct: 85 }, { label: 'Thu', pct: 93 },
  { label: 'Fri', pct: 89 },
];

const typeIcon = { fee_reminder: '💰', attendance_alert: '📅', result: '📝', holiday: '🎉', general: 'ℹ️' };

export default function Dashboard() {
  const [students, setStudents]   = useState([]);
  const [notifs, setNotifs]       = useState([]);
  const [loading, setLoading]     = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    Promise.all([
      API.get('/students?limit=5'),
      API.get('/notifications'),
    ]).then(([s, n]) => {
      setStudents(s.data.students || []);
      setNotifs((n.data || []).slice(0, 4));
    }).catch(() => toast.error('Failed to load dashboard'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <LoadingSpinner />;

  return (
    <div className="space-y-5">
      {/* Greeting */}
      <div>
        <h2 className="text-lg sm:text-xl font-bold text-gray-800">Good morning, Admin 👋</h2>
        <p className="text-gray-400 text-xs sm:text-sm mt-0.5">Here's what's happening at your school today.</p>
      </div>

      {/* Stats — 2 cols on mobile, 4 on desktop */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <StatCard label="Total Students"  value="248"   sub="▲ 12 new this session" icon="👥" />
        <StatCard label="Present Today"   value="91%"   sub="226 / 248 present"      icon="📅" color="text-green-600" />
        <StatCard label="Fee Collected"   value="₹2.1L" sub="April 2025"             icon="💰" color="text-blue-600" />
        <StatCard label="Active Teachers" value="18"    sub="1 on leave"             icon="👨‍🏫" />
      </div>

      {/* Charts — stack on mobile, side-by-side on lg */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <div className="bg-white rounded-xl border border-gray-200 p-4">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-semibold text-gray-700">Fee Collection</h3>
            <span className="text-xs text-gray-400">Last 6 months</span>
          </div>
          <FeeBarChart data={feeChartData} />
        </div>

        <div className="bg-white rounded-xl border border-gray-200 p-4">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-semibold text-gray-700">Attendance This Week</h3>
            <span className="text-xs text-gray-400">%</span>
          </div>
          <AttendanceLineChart data={attChartData} />
        </div>
      </div>

      {/* Bottom row — stack on mobile */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Recent students */}
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="flex justify-between items-center px-4 sm:px-5 py-4 border-b border-gray-100">
            <h3 className="text-sm font-semibold text-gray-700">Recent Students</h3>
            <button
              onClick={() => navigate('/admin/students')}
              className="text-xs text-blue-500 hover:text-blue-700 font-medium"
            >
              View all →
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm" style={{ minWidth: '320px' }}>
              <tbody>
                {students.map(s => (
                  <tr key={s.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors">
                    <td className="px-4 sm:px-5 py-3">
                      <div className="flex items-center gap-2.5">
                        <Avatar name={`${s.first_name} ${s.last_name}`} size="sm" />
                        <div className="min-w-0">
                          <p className="font-medium text-gray-800 text-sm truncate">
                            {s.first_name} {s.last_name}
                          </p>
                          <p className="text-xs text-gray-400">{s.student_id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-3 py-3 text-gray-500 text-xs whitespace-nowrap">
                      {s.class} - {s.section}
                    </td>
                    <td className="px-3 py-3 whitespace-nowrap">
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${feeStatusColor[s.fee_status] || 'bg-gray-100 text-gray-500'}`}>
                        {s.fee_status || 'unpaid'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Notifications */}
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="flex justify-between items-center px-4 sm:px-5 py-4 border-b border-gray-100">
            <h3 className="text-sm font-semibold text-gray-700">Notifications</h3>
            <button
              onClick={() => navigate('/admin/notifications')}
              className="text-xs text-blue-500 hover:text-blue-700 font-medium"
            >
              View all →
            </button>
          </div>
          <div className="divide-y divide-gray-50">
            {notifs.map(n => (
              <div key={n.id} className={`flex gap-3 px-4 sm:px-5 py-3.5 hover:bg-gray-50 ${!n.is_read ? 'bg-blue-50/40' : ''}`}>
                <span className="text-lg mt-0.5 flex-shrink-0">{typeIcon[n.type] || 'ℹ️'}</span>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start gap-2">
                    <p className={`text-sm truncate ${n.is_read ? 'font-normal text-gray-700' : 'font-semibold text-gray-800'}`}>
                      {n.title}
                    </p>
                    {!n.is_read && <div className="w-2 h-2 rounded-full bg-blue-500 flex-shrink-0 mt-1.5" />}
                  </div>
                  <p className="text-xs text-gray-400 mt-0.5 truncate">{n.message}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}