import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import StatCard from '../../components/common/StatCard';

const todaySchedule = [
  { period: '1st — 8:00',  subject: 'Mathematics',    teacher: 'Mrs. Verma' },
  { period: '2nd — 9:00',  subject: 'English',         teacher: 'Ms. Dubey' },
  { period: '3rd — 10:00', subject: 'Science',         teacher: 'Mr. Joshi' },
  { period: '4th — 11:00', subject: 'Social Studies',  teacher: 'Mr. Tiwari' },
  { period: '5th — 12:00', subject: 'Hindi',           teacher: 'Mrs. Mishra' },
];

export default function ParentDashboard() {
  const { user }   = useAuth();
  const navigate   = useNavigate();
  const student    = user?.linkedStudent;

  const quickLinks = [
    { icon: '📅', label: 'Attendance',  path: '/parent/attendance',    color: 'bg-green-50 border-green-200' },
    { icon: '📋', label: 'Report Card', path: '/parent/report-card',   color: 'bg-blue-50 border-blue-200' },
    { icon: '💰', label: 'Fee Status',  path: '/parent/fees',          color: 'bg-yellow-50 border-yellow-200' },
    { icon: '🔔', label: 'Notifications',path: '/parent/notifications', color: 'bg-purple-50 border-purple-200' },
  ];

  return (
    <div className="space-y-5">
      {/* Greeting */}
      <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-2xl p-4 sm:p-5 text-white">
        <p className="text-blue-200 text-xs sm:text-sm">Welcome back</p>
        <h2 className="text-lg sm:text-xl font-bold mt-0.5">{user?.name}</h2>
        {student && (
          <p className="text-blue-200 text-xs sm:text-sm mt-1">
            {student.first_name} {student.last_name} · {student.class} - {student.section}
          </p>
        )}
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-3 sm:gap-4">
        <StatCard label="Attendance"      value="92%"  sub="April 2025"  color="text-green-600" />
        <StatCard label="Average Marks"   value="85%"  sub="Half Yearly" />
        <StatCard label="Fee Status"      value="Paid" sub="April 2025"  color="text-green-600" />
        <StatCard label="Notifications"   value="2"    sub="Unread"      color="text-blue-600" />
      </div>

      {/* Quick links */}
      <div className="grid grid-cols-2 gap-3">
        {quickLinks.map(link => (
          <button
            key={link.path}
            onClick={() => navigate(link.path)}
            className={`flex items-center gap-3 p-4 ${link.color} border rounded-xl transition-all active:scale-95 text-left`}
          >
            <span className="text-2xl">{link.icon}</span>
            <span className="font-medium text-sm text-gray-700">{link.label}</span>
          </button>
        ))}
      </div>

      {/* Today's timetable */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        <div className="px-4 sm:px-5 py-4 border-b border-gray-100">
          <h3 className="text-sm font-semibold text-gray-700">Today's Timetable</h3>
        </div>
        <div className="divide-y divide-gray-50">
          {todaySchedule.map((cls, i) => (
            <div key={i} className="flex items-center gap-3 px-4 sm:px-5 py-3">
              <div className="w-7 h-7 rounded-lg bg-blue-100 text-blue-600 text-xs font-bold flex items-center justify-center flex-shrink-0">
                {i + 1}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-800 truncate">{cls.subject}</p>
                <p className="text-xs text-gray-400">{cls.teacher}</p>
              </div>
              <span className="text-xs text-gray-400 flex-shrink-0">{cls.period.split('—')[0].trim()}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}