import { useAuth } from '../../context/AuthContext';

export default function TopBar({ title, onMenuClick }) {
  const { user } = useAuth();

  const today = new Date().toLocaleDateString('en-IN', {
    weekday: 'short', day: '2-digit', month: 'short', year: 'numeric'
  });

  return (
    <header className="h-14 bg-white border-b border-gray-200 px-4 flex items-center justify-between flex-shrink-0 sticky top-0 z-20">
      <div className="flex items-center gap-3">
        {/* Hamburger — mobile only */}
        <button
          onClick={onMenuClick}
          className="lg:hidden p-2 rounded-lg text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors"
          aria-label="Open menu"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>

        <h1 className="text-sm sm:text-base font-semibold text-gray-800 truncate">{title}</h1>
      </div>

      <div className="flex items-center gap-2 sm:gap-4">
        {/* Date — hidden on very small screens */}
        <span className="hidden sm:block text-xs text-gray-400">{today}</span>

        {/* User avatar */}
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 text-xs font-semibold flex items-center justify-center flex-shrink-0">
            {user?.name?.[0]?.toUpperCase()}
          </div>
          <span className="hidden md:block text-xs font-medium text-gray-700 max-w-[120px] truncate">
            {user?.name}
          </span>
        </div>
      </div>
    </header>
  );
}